package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId string // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsIdx int64 // PIC 9 len=1 = 0
var WsTier int64 // PIC 9 len=1 = 0
var WsComm decimal.Decimal // PIC 9(6)V99 len=8 = 0
var WsTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsSalesEd string // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string // PIC 9.99 len=4
var WsCommEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14

var tierLimit [5]decimal.Decimal
var tierRate [5]decimal.Decimal

var curRec SalesRec
var inputLines []string
var inputPos int
var inputDone bool

func fitDecimal(v decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	// keep low-order digits that fit
	modExp := intDigits + scale
	mod := decimal.New(1, modExp) // 10^(int+scale)
	// scale value to integer
	scaled := v.Shift(scale).Truncate(0)
	// truncate toward zero already; now mod
	r := scaled.Mod(mod)
	// decimal Mod keeps sign of dividend; ok
	return r.Shift(-scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	// find scale = number of 9 after '.'
	dot := strings.Index(pic, ".")
	scale := int32(0)
	if dot >= 0 {
		for _, c := range pic[dot+1:] {
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	// MOVE truncates toward zero
	t := v.Truncate(scale)
	neg := t.IsNegative()
	if neg {
		t = t.Neg()
	}
	// split integer / fraction
	s := t.String()
	// ensure decimal point handling via Shift
	intPart := t.Truncate(0)
	fracPart := t.Sub(intPart)
	// integer digits string
	intStr := intPart.StringFixed(0) // no exponent
	// StringFixed may include "-" but we removed sign
	if strings.Contains(intStr, ".") {
		intStr = strings.Split(intStr, ".")[0]
	}
	// fraction digits
	fracStr := ""
	if scale > 0 {
		// fracPart * 10^scale
		fscaled := fracPart.Shift(scale).Truncate(0)
		fstr := fscaled.StringFixed(0)
		// pad left with zeros to scale
		for int32(len(fstr)) < scale {
			fstr = "0" + fstr
		}
		// keep low-order if too long (shouldn't)
		if int32(len(fstr)) > scale {
			fstr = fstr[len(fstr)-int(scale):]
		}
		fracStr = fstr
		_ = s
	}
	// collect integer slots count
	intPic := pic
	if dot >= 0 {
		intPic = pic[:dot]
	}
	slotCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			slotCount++
		}
	}
	// keep low-order digits
	if len(intStr) > slotCount {
		intStr = intStr[len(intStr)-slotCount:]
	}
	// pad left zeros to slotCount
	for len(intStr) < slotCount {
		intStr = "0" + intStr
	}
	// build integer part output
	var b strings.Builder
	digitIdx := 0
	suppressed := true
	// need digits array
	digits := []byte(intStr)
	for _, c := range intPic {
		switch c {
		case 'Z':
			d := digits[digitIdx]
			digitIdx++
			if suppressed && d == '0' {
				b.WriteByte(' ')
			} else {
				b.WriteByte(d)
				suppressed = false
			}
		case '9':
			d := digits[digitIdx]
			digitIdx++
			b.WriteByte(d)
			suppressed = false
		case ',':
			if suppressed {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		default:
			b.WriteByte(byte(c))
		}
	}
	if dot >= 0 {
		b.WriteByte('.')
		fracPic := pic[dot+1:]
		fi := 0
		for _, c := range fracPic {
			if c == '9' || c == 'Z' {
				if fi < len(fracStr) {
					b.WriteByte(fracStr[fi])
					fi++
				} else {
					b.WriteByte('0')
				}
			} else {
				b.WriteByte(byte(c))
			}
		}
	}
	return b.String()
}

func loadInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file -> treat as empty (EOF immediately)
		inputLines = nil
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// strip trailing \r if present
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
		inputLines = append(inputLines, line)
	}
}

func parseRec(line string) SalesRec {
	// pad with spaces on right to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	id := line[0:4]
	sfield := line[4:12]
	// parse digits only with implied 2 decimals
	t := strings.TrimSpace(sfield)
	var v decimal.Decimal
	if t == "" {
		v = decimal.Zero
	} else {
		// keep digits; if contains non-digit, treat non-digits as zero? Just parse digits
		// Build integer from digits
		neg := false
		digits := ""
		for _, c := range t {
			if c >= '0' && c <= '9' {
				digits += string(c)
			} else if c == '-' {
				neg = true
			}
		}
		if digits == "" {
			v = decimal.Zero
		} else {
			n, _ := decimal.NewFromString(digits)
			// digits string may be big but fits int64? use decimal shift
			v = n.Shift(-2)
			if neg {
				v = v.Neg()
			}
		}
	}
	return SalesRec{SrId: id, SrSales: v}
}

func INITPARA() {
	tierLimit[1] = decimal.NewFromFloat(1000.00)
	tierRate[1] = decimal.NewFromFloat(2.50)
	tierLimit[2] = decimal.NewFromFloat(5000.00)
	tierRate[2] = decimal.NewFromFloat(4.00)
	tierLimit[3] = decimal.NewFromFloat(20000.00)
	tierRate[3] = decimal.NewFromFloat(5.50)
	tierLimit[4] = decimal.NewFromFloat(999999.99)
	tierRate[4] = decimal.NewFromFloat(7.25)
	// ensure exact scales
	tierLimit[1] = decimal.New(100000, -2)
	tierRate[1] = decimal.New(250, -2)
	tierLimit[2] = decimal.New(500000, -2)
	tierRate[2] = decimal.New(400, -2)
	tierLimit[3] = decimal.New(2000000, -2)
	tierRate[3] = decimal.New(550, -2)
	tierLimit[4] = decimal.New(99999999, -2)
	tierRate[4] = decimal.New(725, -2)
}

func READPARA() {
	if inputPos >= len(inputLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	inputPos++
	curRec = parseRec(line)
}

func PROCESSPARA() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if curRec.SrSales.Cmp(tierLimit[WsIdx]) <= 0 {
			WsTier = WsIdx % 10 // PIC 9 store low-order
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * RATE / 100
	exact := curRec.SrSales.Mul(tierRate[WsTier]).Shift(-2)
	r := exact.Round(2)
	WsComm = fitDecimal(r, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	// ADD overflow handling for 9(9)V99: mod 10^11 scaled? Apply fit truncated
	WsTotal = fitDecimal(WsTotal.Truncate(2), 9, 2)
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatEdited(curRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(tierRate[WsTier], "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	tierStr := fmt.Sprintf("%01d", WsTier)
	fmt.Printf("%s T%s %s %s%% %s\n", curRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsIdx = 0
	WsTier = 0
	WsComm = decimal.Zero
	WsTotal = decimal.Zero
	WsCount = 0
	INITPARA()
	loadInput()
	inputPos = 0
	inputDone = false
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	SUMMARYPARA()
}
